import numpy as np
def equation(eps, T, params):
    p = params
    a = p[0] + p[1]*T + p[2]/T
    return a + (p[3]+p[4]/T)*eps + (p[5]+p[6]*T)*eps**2 + p[7]*eps**3 + p[8]*np.log(eps)*T + p[9]*np.log(eps)
